head.script:
scwin.checkLog = function() {
    //return WebSquare.logger.getErrorLog();
    var log = WebSquare.logger.getLog()
    return (log.indexOf("3===4") != -1) && (log.indexOf("2===2") != -1);
}
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.checkLog()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    window.jsonData = [{
            "col1": "1111",
            "col2": "2222"
        },
        {
            "col1": "3333",
            "col2": "4444"
        }
    ];
    dl_rcptInfo.setJSON(jsonData);
    spn_cntGrpPrsts.setLabel("3");
    spn_totCntGrpPrsts.setValue("4");
    //alert(spn_cntGrpPrsts.getLabel() +"==="+ spn_totCntGrpPrsts.getValue() );
    WebSquare.logger.printLog(spn_cntGrpPrsts.getLabel() + "===" + spn_totCntGrpPrsts.getValue());
    //데이터리스트 dl_rcptInfo 의 행을 생성해놓고
    spn_cntGrpPrsts.setLabel(dl_rcptInfo.getRowCount());
    spn_totCntGrpPrsts.setValue(dl_rcptInfo.getRowCount());
    //alert(spn_cntGrpPrsts.getLabel() +"==="+ spn_totCntGrpPrsts.getValue() );
    WebSquare.logger.printLog(spn_cntGrpPrsts.getLabel() + "===" + spn_totCntGrpPrsts.getValue());
    //데이터리스트 dl_rcptInfo 의 행을 생성해놓고 변수에 담아서
    window.temp = dl_rcptInfo.getRowCount();
    spn_cntGrpPrsts.setLabel(temp);
    spn_totCntGrpPrsts.setValue(temp);
    //alert(spn_cntGrpPrsts.getLabel() +"==="+ spn_totCntGrpPrsts.getValue() );
    WebSquare.logger.printLog(spn_cntGrpPrsts.getLabel() + "===" + spn_totCntGrpPrsts.getValue());
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
